INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schlüssel-Wert-Datenbanken immer schneller als relationale sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Anwendungsfall ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Datenbank für schnelle Cache-Zugriffe wähle?', 3, '[{"text": "Einfache Struktur", "correct": true, "because": "Optimiert Zugriffsgeschwindigkeit"}, {"text": "Komplexe Joins", "correct": false, "because": "Nicht typisch"}, {"text": "Detaillierte Schemata", "correct": false, "because": "Verlangsamt Zugriffe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen Schlüssel-Wert-Datenbanken nützlich?', 5, '[{"text": "Hohe Skalierbarkeit", "correct": true, "because": "Verteilt Daten leicht"}, {"text": "Schnelle Abfragen", "correct": true, "because": "Einfache Struktur"}, {"text": "Komplexe Beziehungen", "correct": false, "because": "Nicht dafür geeignet"}, {"text": "Strenge Schemata", "correct": false, "because": "Flexibel ohne Schema"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schlüssel-Wert-Datenbanken speichern einfache Paare. b) Sie unterstützen komplexe SQL-Joins.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Joins sind nicht typisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Datenbank für Session-Daten wähle?', 4, '[{"text": "Zugriffsgeschwindigkeit", "correct": false, "because": "Entscheidend für Sessions"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Lasten"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Datenbankfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schlüssel-Wert-Datenbanken Schemata voraussetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel ohne festes Schema"}, {"text": "Ja", "correct": false, "because": "Kein Schema erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt am besten für eine Schlüssel-Wert-Datenbank?', 3, '[{"text": "Web-Caching", "correct": true, "because": "Schnelle, einfache Zugriffe"}, {"text": "Komplexe Berichte", "correct": false, "because": "Beziehungen nötig"}, {"text": "Langzeitarchivierung", "correct": false, "because": "Andere Systeme besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für Schlüssel-Wert-Datenbanken entscheidend?', 5, '[{"text": "Einfache Abfragen", "correct": true, "because": "Schnelle Datenlieferung"}, {"text": "Horizontale Skalierung", "correct": true, "because": "Verteilt Lasten"}, {"text": "Strenge Konsistenz", "correct": false, "because": "Oft eventual consistency"}, {"text": "SQL-Standard", "correct": false, "because": "NoSQL-Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Redis ist eine Schlüssel-Wert-Datenbank. b) Sie speichert immer relationale Daten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Redis ist nicht relational"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Schlüssel-Wert-Datenbank?', 4, '[{"text": "Schneller Zugriff", "correct": false, "because": "Kernfunktion"}, {"text": "Schlüssel-Design", "correct": false, "because": "Definiert Daten"}, {"text": "Komplexe Joins", "correct": true, "because": "Nicht unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Schlüssel-Wert-Datenbanken für Finanztransaktionen ideal?', 2, '[{"text": "Nein", "correct": true, "because": "Brauchen oft stärkere Konsistenz"}, {"text": "Ja", "correct": false, "because": "Andere Systeme besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Schlüssel-Wert-Datenbank?', 4, '[{"text": "Hohe Geschwindigkeit", "correct": true, "because": "Einfache Struktur"}, {"text": "Flexibilität", "correct": true, "because": "Kein festes Schema"}, {"text": "Komplexe Analysen", "correct": false, "because": "Nicht dafür geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schlüssel-Wert-Datenbanken keine Skalierung brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierung ist oft nötig"}, {"text": "Ja", "correct": false, "because": "Skalierung ist Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich für eine Schlüssel-Wert-Datenbank, um Benutzerdaten zu speichern?', 3, '[{"text": "Eindeutige Schlüssel", "correct": true, "because": "Ermöglicht schnellen Zugriff"}, {"text": "Komplexe Tabellen", "correct": false, "because": "Nicht nötig"}, {"text": "Grafische Tools", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schlüssel-Wert-Datenbanken sind NoSQL. b) Sie ersetzen immer relationale Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Schlüssel-Wert-Datenbanken effektiv?', 5, '[{"text": "Einfache Datenstruktur", "correct": true, "because": "Schnelle Zugriffe"}, {"text": "Verteilte Architektur", "correct": true, "because": "Skaliert gut"}, {"text": "Komplexe Beziehungen", "correct": false, "because": "Nicht unterstützt"}, {"text": "Langsame Abfragen", "correct": false, "because": "Ziel ist Geschwindigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Schlüssel-Wert-Datenbank einrichte?', 3, '[{"text": "Schlüssel-Design", "correct": false, "because": "Definiert Zugriff"}, {"text": "Skalierungsplan", "correct": false, "because": "Wichtig für Lasten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Datenbankfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützen Schlüssel-Wert-Datenbanken relationale Abfragen?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf einfache Zugriffe"}, {"text": "Ja", "correct": false, "because": "Nicht dafür ausgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schlüssel-Wert-Datenbanken für Echtzeit-Analysen geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Schnelle Zugriffe möglich"}, {"text": "Nein", "correct": false, "because": "Für einfache Daten geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend für eine Schlüssel-Wert-Datenbank?', 4, '[{"text": "Schnelle Lesezugriffe", "correct": true, "because": "Optimiert Performance"}, {"text": "Komplexe Joins", "correct": false, "because": "Nicht unterstützt"}, {"text": "Feste Schemata", "correct": false, "because": "Flexibel ohne Schema"}]');
